-- THE CATALOGUE KNOWS THE PLAIN WORDS SUPPLIERS USE (12 Nov 2026, sales_engineer).
-- Seat: sales_engineer. Founder ruling 1647: "the agent must read a supplier's profile really well ... recruitment: what
-- sort of staff do they supply? Labourers? Professional experts or freelancers? ... if that step is done wrong, everything
-- goes wrong after that. We will struggle a lot with cross-matching later." APPLY AFTER the three catalogue files
-- (the_catalogue_can_name_what_suppliers_do.sql, the_same_work_under_two_keys_meets_at_the_service_gate.sql,
-- a_demo_supplier_never_feeds_the_alias_queue.sql): it names services and implication rows they wrote.
--
-- MEASURED (production htdblwldjkcgjvmqkbeh, read-only, 12 Nov 2026):
--   * 874 of the 1,151 active services had NO alias at all: the reading (supplier_profile_reading.ts nameIndex /
--     codeKeysOf) could place a supplier's phrase on them by code only when he wrote the catalogue's label exactly
--     ("Manned guarding", "Kiosks & pop-ups", "Onsite clinic & nurse staffing"), never in his own words.
--   * The recruitment card (svc-questions review, round 3, finding 6) left in his words: office staff, supervisors,
--     professionals / professional staff, chefs, cooks, truck and delivery drivers, nurses, security guards, kiosks.
--   * The 16 hard profiles (scripts/e2e/services_hard_profiles, the recorded run) hold 202 phrases whose answer-key
--     service no name said ("Cornices", "Parquet flooring", "SMDB panels", "Shopfront signs", "Termite control", ...):
--     each reached its key only through the model.
--   * Two notes of the catalogue review (svc-catalogue REVIEW.md, round 2): queue rows 205 "تنظيف فلل" and 206
--     "تنظيف شقق" were still 'approved' under cleaning.deep_cleaning though the catalogue file had moved both names to
--     cleaning.residential (rows 35076, 35216); and a roof or wall insulation specialist was not reached for a request
--     keyed waterproofing.thermal (only the forward rows waterproofing.thermal -> roof / wall insulation existed).
--
-- THE CONVENTION (read from the live queue and its routines, kept here): ONE NAME, ONE KEY. fn_service_alias_decide
-- refuses an approval whose phrase fn_service_alias_owners finds on another active service (its key, code, either label
-- or any alias, compared through fn_service_alias_norm), and the catalogue file's guard refuses the same. There is no
-- exception for `same` twins: twins share their work through the `same` implication rows, never a shared name
-- ("security guard" is security_systems.guarding's; its twin security_guarding.manned_guarding gets "security guards",
-- "manned guarding services", never "security guard"). Each alias below was also checked offline against every live name
-- in the reading's own shape (supplier_trade_choice.ts quoteKey, "and"/"the" dropped) and for singular/plural of another
-- service's name; 97 drafted names that another service already owned were dropped, as was "duct cleaning" (queue row
-- 444 rejected it for cleaning.ac_duct as a ZZ DEMO fixture's phrase; the unique (phrase_norm, key) row would contradict it).
--
-- WHAT THIS CHANGES (data only: no routine, no table, no trade, no service is added, renamed or deactivated):
--   1. queue rows 205 and 206 are REJECTED under cleaning.deep_cleaning (cleaning.residential, the right key, already
--      holds both names as approved rows 35076 / 35216; deep_cleaning's aliases no longer carry them).
--   2. two plain implication rows (same = false): thermal_insulation.roof_insulation -> waterproofing.thermal and
--      thermal_insulation.wall_insulation -> waterproofing.thermal (the two trades are curated neighbours already).
--   3. 3,870 curated aliases (3,126 English, 744 Arabic) on 911 services, filed as approved rows of the queue (source
--      curated, decided by sales_engineer) and appended to taxonomy_trade_service.aliases, never replacing a name:
--        - 859 of the 874 services that had none (two to nine plain names each: singular and plural where both are
--          written; the Gulf Arabic trade name where one is in everyday use);
--        - the recruitment card's staff words on labour_supply (office staff, admin staff, supervisors, professionals,
--          professional staff, accounting / finance / IT / HR / sales staff, electricians / masons / carpenters /
--          plumbers / welders supply, steel fixers, chefs, cooks, kitchen staff, drivers, truck / delivery / bus drivers),
--          nurses on occupational_health.onsite_clinic_nurse, security guards on security_guarding.manned_guarding,
--          kiosk / kiosks / pop-up stand on exhibition_stands.kiosks_pop_ups;
--        - the hard profiles' own phrases on the 46 services they named without a matching name.
--      Left WITHOUT a name, on purpose (15): a `same` twin whose partner owns the names (masonry_blockwork.blockwork,
--      masonry_blockwork.plastering, tents_shades.tensile_structures, tents_shades.shade_sails,
--      thermal_insulation.acoustic_insulation, water_treatment.tank_cleaning_disinfection), and a key that duplicates
--      another trade's key with no `same` row yet, so a name would pick one of the two for the sales engineer
--      (machinery_repair / motors_drives.motor_rewinding, flexible_packaging.bubble_wrap_air_cushions /
--      protective_packaging.bubble_wrap, packaging.shrink_sleeves, packaging.strapping, packaging.woven_sacks,
--      packaging.fibc_bags, playground_equipment.shade_sails: the packaging pairs are the review's open note).
--      Not used, as names of one service: bare words a supplier writes for a whole trade or for a contractor rather than
--      staff ("electricians", "masons", "carpenters", "accountants": the staff form "... supply" is used instead; "staff",
--      "supply", "services", "maintenance", "works"), and brand names.
--
-- AT MERGE, AFTER THIS FILE: aliases feed both embedding texts (scripts/kb/embed_taxonomy_services.mjs: embedding_gte of
-- the names and English aliases, embedding_ml of every name and alias), so the 911 services carry a stale sha until
--   node scripts/kb/embed_taxonomy_services.mjs --write    (free, in-region embed_ml; never OpenRouter)
--   node scripts/kb/embed_taxonomy_services.mjs            (must then print "0 stale vector(s)")
-- Until then exact names and aliases work at once and the meaning layer reads the old vectors.
--
-- prevented by: scripts/sql/the_catalogue_knows_the_plain_words_suppliers_use_probe.sql (ZZ DEMO only, rolled back),
--               scripts/checks/the_catalogue_knows_the_plain_words_suppliers_use.test.mjs, and the guard below.

-- ── 1. two names the catalogue file moved are rejected where they were left approved ──────────────────────────────────
update public.service_alias_proposal q
   set status = 'rejected', decided_by = 'sales_engineer', decided_at = now(),
       reason = 'moved to cleaning.residential (a villa or flat cleaned every week is not a deep clean): the catalogue knows the plain words suppliers use, 12 Nov 2026'
 where q.trade_code = 'cleaning' and q.code = 'deep_cleaning' and q.status = 'approved'
   and q.phrase_norm in (public.fn_service_alias_norm('تنظيف فلل'), public.fn_service_alias_norm('تنظيف شقق'))
   and not exists (select 1 from public.taxonomy_trade_service s, unnest(coalesce(s.aliases, '{}'::text[])) a
                    where s.trade_code = 'cleaning' and s.code = 'deep_cleaning' and public.fn_service_alias_norm(a) = q.phrase_norm)
   and exists (select 1 from public.service_alias_proposal r
                where r.trade_code = 'cleaning' and r.code = 'residential' and r.status = 'approved' and r.phrase_norm = q.phrase_norm);

-- ── 2. a roof or wall insulation specialist does the thermal insulation a waterproofing request names ───────────────────
insert into public.service_implication (from_code, implies_trade, implies_code, reason_en, reason_ar, same) values
  ('thermal_insulation.roof_insulation','waterproofing','thermal','A roof or wall insulation contractor carries out the thermal insulation a waterproofing request asks for.','مقاول العزل الحراري للأسطح أو الجدران ينفّذ العزل الحراري المطلوب ضمن أعمال العزل المائي.',false),
  ('thermal_insulation.wall_insulation','waterproofing','thermal','A roof or wall insulation contractor carries out the thermal insulation a waterproofing request asks for.','مقاول العزل الحراري للأسطح أو الجدران ينفّذ العزل الحراري المطلوب ضمن أعمال العزل المائي.',false)
on conflict (from_code, implies_trade, implies_code) do nothing;

