  select string_agg(x->>0 || '.' || (x->>1), ', ') into v_missing
    from jsonb_array_elements(seed) x
   where not exists (select 1 from public.taxonomy_trade_service s where s.active and s.trade_code = x->>0 and s.code = x->>1);
  if v_missing is not null then raise exception 'the seed names services that are not active: %', v_missing; end if;
  -- ONE NAME, ONE KEY: no alias is already a name of ANOTHER active service (key, code, both labels, every alias), twins
  -- included. Every name is normalised ONCE (calling fn_service_alias_owners per alias normalises the whole catalogue
  -- per call; the catalogue file measured that it did not finish in 120 s for 509 names).
  with names as (
    select s.trade_code || '.' || s.code as k, public.fn_service_alias_norm(n) as n
      from public.taxonomy_trade_service s,
           unnest(array[s.trade_code || '.' || s.code, s.code, s.label_en, s.label_ar] || coalesce(s.aliases, '{}'::text[])) n
     where s.active
  ), p as (
    select distinct x->>0 || '.' || (x->>1) as k, lower(btrim(a)) as alias, public.fn_service_alias_norm(a) as n
      from jsonb_array_elements(seed) x, jsonb_array_elements_text(x->2) a
  )
  select string_agg(distinct p.alias || ' -> ' || nm.k, '; ') into v_owned
    from p join names nm on nm.n = p.n and nm.k <> p.k;
  if v_owned is not null then raise exception 'a curated alias already names another service: %', v_owned; end if;
  -- a phrase the queue already decided otherwise for the same key (a rejected or still proposed row) is not overruled here
  select string_agg(q.phrase || ' -> ' || q.trade_code || '.' || q.code || ' (' || q.status || ')', '; ') into v_queued
    from jsonb_array_elements(seed) x, jsonb_array_elements_text(x->2) a
    join public.service_alias_proposal q on q.phrase_norm = public.fn_service_alias_norm(a)
   where q.trade_code = x->>0 and q.code = x->>1 and q.status <> 'approved';
  if v_queued is not null then raise exception 'the queue already decided a curated alias otherwise: %', v_queued; end if;

  insert into public.service_alias_proposal (phrase, phrase_norm, trade_code, code, source, status, decided_by, decided_at, reason)
  select p.alias, public.fn_service_alias_norm(p.alias), p.trade_code, p.code, 'curated', 'approved', 'sales_engineer', now(),
         'curated 12 Nov 2026 (founder ruling 1647): the catalogue knows the plain words suppliers use'
    from (select distinct x->>0 as trade_code, x->>1 as code, lower(btrim(a)) as alias
            from jsonb_array_elements(seed) x, jsonb_array_elements_text(x->2) a) p
  on conflict (phrase_norm, trade_code, code) do nothing;

  -- appended only where a name is missing, so a re-run writes nothing
  update public.taxonomy_trade_service t
     set aliases = coalesce(t.aliases, '{}'::text[])
                || array(select distinct lower(btrim(a)) from jsonb_array_elements(seed) x, jsonb_array_elements_text(x->2) a
                          where x->>0 = t.trade_code and x->>1 = t.code
                            and not (lower(btrim(a)) = any(coalesce(t.aliases, '{}'::text[])))
                          order by 1)
   where exists (select 1 from jsonb_array_elements(seed) x, jsonb_array_elements_text(x->2) a
                  where x->>0 = t.trade_code and x->>1 = t.code
                    and not (lower(btrim(a)) = any(coalesce(t.aliases, '{}'::text[]))));
end
$seed$;

-- Verdict row (a data file with a guard: the guard raises and refuses the apply; this row reports what landed). PROBE OK
-- only when every row the file meant to write is there: the 3870 approved queue rows, each name on its service, the
-- two implication rows, the two rejections, and only the 15 services named above still without a name.
select case
  when (select count(*) from public.service_alias_proposal q
         where q.source = 'curated' and q.status = 'approved' and q.decided_by = 'sales_engineer'
           and q.reason = 'curated 12 Nov 2026 (founder ruling 1647): the catalogue knows the plain words suppliers use'
           and exists (select 1 from public.taxonomy_trade_service s where s.active and s.trade_code = q.trade_code and s.code = q.code
                         and lower(btrim(q.phrase)) = any(s.aliases))) = 3870
   and (select count(*) from public.service_implication where active and not same and implies_trade = 'waterproofing' and implies_code = 'thermal'
          and from_code in ('thermal_insulation.roof_insulation', 'thermal_insulation.wall_insulation')) = 2
   and not exists (select 1 from public.service_alias_proposal where id in (205, 206) and status <> 'rejected')
   and not exists (select 1 from public.taxonomy_trade_service where trade_code = 'cleaning' and code = 'deep_cleaning'
                     and aliases && array['تنظيف فلل', 'تنظيف شقق'])
   and (select count(*) from public.taxonomy_trade_service s where s.active and coalesce(cardinality(s.aliases), 0) = 0
          and s.trade_code || '.' || s.code <> all (array[
            'masonry_blockwork.blockwork','masonry_blockwork.plastering','tents_shades.tensile_structures','tents_shades.shade_sails',
            'thermal_insulation.acoustic_insulation','water_treatment.tank_cleaning_disinfection','machinery_repair.motor_rewinding',
            'motors_drives.motor_rewinding','flexible_packaging.bubble_wrap_air_cushions','protective_packaging.bubble_wrap',
            'packaging.shrink_sleeves','packaging.strapping','packaging.woven_sacks','packaging.fibc_bags','playground_equipment.shade_sails'])) = 0
  then 'PROBE OK the catalogue knows the plain words suppliers use: 3870 names on 911 services, two implications, two rejections'
  else 'PROBE FAILED: a curated name, an implication row or a rejection is missing' end as verdict;
